from datetime import date

import pytest

from late_fee_calculator import LateFeeCalculator

DUE = date(2025, 1, 6)  # Monday


def calc(today):
    return LateFeeCalculator(today=today)


# ---- __init__ ----
def test_default_today_is_date_today():
    assert LateFeeCalculator()._today == date.today()


def test_explicit_today_used():
    assert calc(date(2025, 1, 1))._today == date(2025, 1, 1)


# ---- _weekday_days_between ----
def test_between_end_before_start_is_zero():
    assert calc(DUE)._weekday_days_between(date(2025, 1, 10), date(2025, 1, 6)) == 0


def test_between_same_day_is_zero():
    assert calc(DUE)._weekday_days_between(DUE, DUE) == 0


def test_between_counts_weekdays_only():
    # Mon Jan 6 .. Mon Jan 13 (end exclusive): Mon-Fri = 5, Sat/Sun skipped
    assert calc(DUE)._weekday_days_between(DUE, date(2025, 1, 13)) == 5


def test_between_weekend_only_is_zero():
    # Sat Jan 4 .. Mon Jan 6: Sat + Sun
    assert calc(DUE)._weekday_days_between(date(2025, 1, 4), date(2025, 1, 6)) == 0


# ---- compute_fee_cents: zero paths ----
@pytest.mark.parametrize("balance", [0, -1, -100000])
def test_nonpositive_balance_zero_fee(balance):
    assert calc(date(2026, 1, 1)).compute_fee_cents(balance, DUE) == 0


def test_not_yet_due_zero_fee():
    assert calc(date(2025, 1, 1)).compute_fee_cents(1_000_000, DUE) == 0


def test_within_grace_zero_fee():
    assert calc(date(2025, 1, 10)).compute_fee_cents(1_000_000, DUE) == 0


def test_exactly_grace_boundary_zero_fee():
    # 10 weekdays elapsed -> billable 0
    assert calc(date(2025, 1, 20)).compute_fee_cents(1_000_000, DUE) == 0


def test_weekends_not_counted_toward_grace():
    # Sat Jan 4 -> Sat Jan 18: 14 calendar days but only 10 weekdays
    assert calc(date(2025, 1, 18)).compute_fee_cents(1_000_000, date(2025, 1, 4)) == 0


# ---- compute_fee_cents: fee paths ----
def test_one_billable_day_normal_fee():
    # 11 weekdays -> 1 billable; 10_000_000 * 0.0005 = 5000
    assert calc(date(2025, 1, 21)).compute_fee_cents(10_000_000, DUE) == 5000


def test_multiple_billable_days():
    # Jan 6 -> Jan 24: 14 weekdays -> 4 billable; 10_000_000*0.0005*4 = 20000
    assert calc(date(2025, 1, 24)).compute_fee_cents(10_000_000, DUE) == 20000


def test_minimum_fee_applied():
    # raw = 100000*0.0005*1 = 50 -> min 500
    assert calc(date(2025, 1, 21)).compute_fee_cents(100_000, DUE) == 500


def test_max_cap_applied():
    # 520 weekdays -> 510 billable; raw 25500 > cap 25000
    assert calc(date(2027, 1, 4)).compute_fee_cents(100_000, DUE) == 25000


def test_tiny_balance_min_beats_cap():
    # cap = 25 cents, but min 500 wins
    assert calc(date(2025, 1, 21)).compute_fee_cents(100, DUE) == 500


def test_round_half_up():
    today = date(2025, 1, 21)  # 1 billable day
    assert calc(today).compute_fee_cents(2_001_001, DUE) == 1001  # 1000.5005
    assert calc(today).compute_fee_cents(2_000_999, DUE) == 1000  # 1000.4995
